const results = [];

for (const item of items) {
  const rawOutput = item.json.output;

  try {
    // Trường hợp đặc biệt: "null" dạng chuỗi hoặc giá trị null
    if (rawOutput === "null" || rawOutput === null) {
      results.push({
        json: {
          info: "Output is null",
          raw: rawOutput
        }
      });
      continue;
    }

    const parsed = JSON.parse(rawOutput);

    // Nếu parse xong vẫn là null
    if (parsed === null) {
      results.push({
        json: {
          info: "Parsed result is null",
          raw: rawOutput
        }
      });
      continue;
    }

    // Đưa về mảng nếu không phải mảng
    const normalized = Array.isArray(parsed) ? parsed : [parsed];

    for (const obj of normalized) {
      // Đảm bảo obj là object (không phải string, number, boolean,...)
      if (typeof obj === 'object' && obj !== null) {
        results.push({ json: obj });
      } else {
        results.push({
          json: {
            error: true,
            message: "Parsed item is not an object",
            value: obj
          }
        });
      }
    }
  } catch (err) {
    results.push({
      json: {
        error: true,
        message: "Failed to parse output",
        raw: rawOutput,
      }
    });
  }
}

return results;

// Lấy danh sách thông báo từ input
const notifications = items.map(item => item.json);

// Nếu không có thông báo
if (notifications.length === 0) {
  return [
    {
      json: {
        status: "error",
        message: "❌ Không có lớp nào để thông báo."
      }
    }
  ];
}

// Gom nhóm theo phần message sau tên lớp
const messageMap = {};

for (const n of notifications) {
  // Tách tên lớp (sau chữ "Lớp")
  const match = n.message.match(/Lớp\s+([A-Z0-9]+)/i);
  const className = match ? match[1] : "Không xác định";

  // Lấy phần nội dung còn lại sau tên lớp
  const messageBody = n.message.replace(/Lớp\s+[A-Z0-9]+\s*/i, "").trim();

  // Gom các lớp có cùng nội dung messageBody
  if (!messageMap[messageBody]) messageMap[messageBody] = [];
  messageMap[messageBody].push(className);
}

// Tạo danh sách kết quả
const results = [];

for (const [body, classes] of Object.entries(messageMap)) {
  const combinedClasses = classes.join(", ");
  const lecturerMessage = `✅ Đã đặt thông báo: Lớp ${combinedClasses} ${body}`;
  results.push({
    json: {
      status: "success",
      lecturerMessage
    }
  });
}

return results;

