// Giả sử input từ node trước truyền vào là dạng như sau:
const rawOutput = items[0].json.output;

// Bước 1: Loại bỏ dấu ```json và ``` ở đầu/cuối
const cleanedJsonString = rawOutput
  .replace(/^```json\n/, '')  // Bỏ phần mở đầu ```json\n
  .replace(/```$/, '')        // Bỏ phần kết thúc ```

// Bước 2: Parse chuỗi JSON thành đối tượng thật
const parsed = JSON.parse(cleanedJsonString);

// Trả kết quả
return [
  {
    json: parsed
  }
];

return items.map(item => {
  const data = item.json?.message?.data || {};
  let content = data.content || "";
  let quoteMsg = data.quote?.msg || "";

  // 1. Xóa @Btec Ai Teacher Assistant trong content
  content = content.replace(/@Btec Ai Teacher Assistant/gi, "").trim();

  // 2. Parse quote.msg -> tách Name và Question
  let msg_name = "";
  let msg_content = "";

  const nameMatch = quoteMsg.match(/Name:\s*([^\n]+)/i);
  if (nameMatch) {
    msg_name = nameMatch[1].trim();
  }

  const questionMatch = quoteMsg.match(/Question:\s*(.+)/i);
  if (questionMatch) {
    msg_content = questionMatch[1].trim();
  }

  return {
    json: {
      message: {
        data: {
          content,
          quote: {
            msg_name,
            msg_content
          }
        }
      }
    }
  };
});

const results = items.map(item => {
  const data = item.json?.message?.data ?? {};
  const quote = data.quote ?? {};

  const name = (quote.msg_name || 'Bạn').trim();
  const quotedText = (quote.msg_content || '').trim();
  let reply = (data.content || '').trim();

  // Xóa prefix nếu có dạng "@Ai Chatbot Teacher Assistant Demo "
  reply = reply.replace(/^@Ai Chatbot Teacher Assistant Demo\s*/i, '');

  // Chuẩn hóa câu hỏi (thêm ? nếu chưa có)
  const question = quotedText.endsWith("?") ? quotedText : quotedText + "?";

  const output = `👉 Chào ${name}, bạn đã hỏi: "${question}".\nGiáo viên phản hồi: "${reply}"`;

  return {
    json: {
      formatted: output
    }
  };
});

return results;
